selector_to_html = {"a[href=\"#renovate-keeps-re-bumping-a-git-override-commit-i-deliberately-fixed-how-do-i-stop-that\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Renovate keeps re-bumping a <code class=\"docutils literal notranslate\"><span class=\"pre\">git_override</span></code> commit I deliberately fixed. How do I stop that?<a class=\"headerlink\" href=\"#renovate-keeps-re-bumping-a-git-override-commit-i-deliberately-fixed-how-do-i-stop-that\" title=\"Link to this heading\">\uf0c1</a></h2><p>Renovate\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">bazel-module</span></code> manager tracks <code class=\"docutils literal notranslate\"><span class=\"pre\">git_override</span></code>/<code class=\"docutils literal notranslate\"><span class=\"pre\">archive_override</span></code>\ncommits like any other dependency version, and will bump a manually-vetted pin\nto whatever the tracked remote\u2019s branch tip is \u2014 unvalidated. This broke\n<a class=\"reference external\" href=\"https://github.com/michael-christen/toolbox/pull/395\">#395</a> twice: once on the\noriginal bad bump, and again when Renovate silently re-bumped the fork pin we\u2019d\njust fixed.</p><p>Fix: add a <code class=\"docutils literal notranslate\"><span class=\"pre\">packageRules</span></code> entry in <code class=\"docutils literal notranslate\"><span class=\"pre\">.github/renovate.json</span></code> disabling tracking\nfor that package, with a <code class=\"docutils literal notranslate\"><span class=\"pre\">description</span></code> explaining why it\u2019s pinned:</p>", "a[href=\"#why-did-my-bazel-module-renovate-pr-fail-with-a-weird-bzlmod-module-graph-error\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Why did my <code class=\"docutils literal notranslate\"><span class=\"pre\">bazel-module</span></code> Renovate PR fail with a weird bzlmod/module-graph error?<a class=\"headerlink\" href=\"#why-did-my-bazel-module-renovate-pr-fail-with-a-weird-bzlmod-module-graph-error\" title=\"Link to this heading\">\uf0c1</a></h2><p>Most likely a <strong>module extension namespace collision</strong>. Extensions like\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">=</span> <span class=\"pre\">use_extension(...)</span></code> are evaluated once across the whole module graph, so\nevery module\u2019s tags (e.g. <code class=\"docutils literal notranslate\"><span class=\"pre\">pip.parse(hub_name=\"pip\")</span></code>) share one flat namespace.\nIf a dependency declares the same <code class=\"docutils literal notranslate\"><span class=\"pre\">hub_name</span></code> (or similar) we do, bzlmod fails or\nsilently picks one. This happened when emboss\u2019s BCR module declared its own\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> hub, colliding with ours\n(<a class=\"reference external\" href=\"https://github.com/michael-christen/toolbox/pull/436\">#436</a>) \u2014 fixed by\nrenaming our hub to <code class=\"docutils literal notranslate\"><span class=\"pre\">toolbox_pip</span></code>.</p>", "a[href=\"#i-patched-a-dependency-with-single-version-override-but-the-patch-doesnt-seem-to-apply-why\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">I patched a dependency with <code class=\"docutils literal notranslate\"><span class=\"pre\">single_version_override</span></code>, but the patch doesn\u2019t seem to apply. Why?<a class=\"headerlink\" href=\"#i-patched-a-dependency-with-single-version-override-but-the-patch-doesnt-seem-to-apply-why\" title=\"Link to this heading\">\uf0c1</a></h2><p>bzlmod reads a module\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">MODULE.bazel</span></code> <strong>twice</strong>: once during graph discovery\n(straight from the registry, ignoring overrides) and once during fetch (where\n<code class=\"docutils literal notranslate\"><span class=\"pre\">single_version_override</span></code> patches are actually applied). If your patch changes\nanything discovery cares about \u2014 a <code class=\"docutils literal notranslate\"><span class=\"pre\">bazel_dep</span></code>, an extension tag call, the\nmodule\u2019s own declared name/version \u2014 discovery already built the graph without\nit, and the patch never has a chance to matter.</p><p>Fix: use <code class=\"docutils literal notranslate\"><span class=\"pre\">archive_override</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">git_override</span></code> instead, which replace the entire\nsource before either phase runs. To confirm this is what\u2019s happening, check\n<code class=\"docutils literal notranslate\"><span class=\"pre\">MODULE.bazel.lock</span></code> for the module\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">registryFileHashes</span></code> entry \u2014 if it matches\nthe stock (unpatched) registry file, that confirms discovery bypassed the patch.</p>", "a[href=\"#where-do-i-look-before-assuming-a-renovate-failure-is-new\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Where do I look before assuming a Renovate failure is new?<a class=\"headerlink\" href=\"#where-do-i-look-before-assuming-a-renovate-failure-is-new\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#decision-guide-cap-patch-override-or-disable-tracking\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Decision guide: cap, patch, override, or disable tracking?<a class=\"headerlink\" href=\"#decision-guide-cap-patch-override-or-disable-tracking\" title=\"Link to this heading\">\uf0c1</a></h2><p>In order of preference:</p>", "a[href=\"#a-pip-dependency-bump-broke-the-lockfile-even-though-the-pr-looked-fine-why\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">A pip dependency bump broke the lockfile even though the PR looked fine. Why?<a class=\"headerlink\" href=\"#a-pip-dependency-bump-broke-the-lockfile-even-though-the-pr-looked-fine-why\" title=\"Link to this heading\">\uf0c1</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">hashin</span></code> (which Renovate uses under the hood for <code class=\"docutils literal notranslate\"><span class=\"pre\">pip_requirements</span></code>) patches one\npackage\u2019s pin without checking whether a <em>sibling</em> package requires it at a\nspecific version. Two cases seen so far:</p>", "a[href=\"#renovate-faq\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Renovate FAQ<a class=\"headerlink\" href=\"#renovate-faq\" title=\"Link to this heading\">\uf0c1</a></h1><p>Common problems seen when a Renovate PR goes red in this repo, and how they\u2019ve\nbeen resolved. For an automated triage flow, see the <code class=\"docutils literal notranslate\"><span class=\"pre\">renovate-debug</span></code> Claude\nCode skill (<code class=\"docutils literal notranslate\"><span class=\"pre\">.claude/skills/renovate-debug/SKILL.md</span></code>), which covers the same\nground in a format meant to be followed step-by-step.</p>", "a[href=\"#bazel-says-content-does-not-match-target-on-my-patch-but-patch-git-apply-applies-it-fine-locally-why\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Bazel says <code class=\"docutils literal notranslate\"><span class=\"pre\">CONTENT_DOES_NOT_MATCH_TARGET</span></code> on my patch, but <code class=\"docutils literal notranslate\"><span class=\"pre\">patch</span></code>/<code class=\"docutils literal notranslate\"><span class=\"pre\">git</span> <span class=\"pre\">apply</span></code> applies it fine locally. Why?<a class=\"headerlink\" href=\"#bazel-says-content-does-not-match-target-on-my-patch-but-patch-git-apply-applies-it-fine-locally-why\" title=\"Link to this heading\">\uf0c1</a></h2><p>Bazel doesn\u2019t use system <code class=\"docutils literal notranslate\"><span class=\"pre\">patch</span></code> \u2014 it has its own, stricter unified-diff\napplier. Two known trip-ups:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
